window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"k4A7JfpwgZI","speaker":"Hristijan Mickoski","role":"President of the Government","country":"North Macedonia","region":"Europe","url":"https://www.youtube.com/watch?v=k4A7JfpwgZI","date":"20260925","title":"🇲🇰 North Macedonia - President of the Government Addresses UN General Debate, 81st Session","seconds":1552,"words":3217,"counts":{"claims":39,"promises":2,"attacks":0},"topics":[{"topic":"EU integration","share":0.0945,"seconds":147},{"topic":"North Macedonia education","share":0.0833,"seconds":129},{"topic":"Institutional trust","share":0.0792,"seconds":123},{"topic":"Small states","share":0.0734,"seconds":114},{"topic":"North Macedonia EU accession","share":0.0527,"seconds":82},{"topic":"AI infrastructure","share":0.0455,"seconds":71},{"topic":"North Macedonia foreign policy","share":0.0451,"seconds":70},{"topic":"Migration policy","share":0.0427,"seconds":66},{"topic":"International order","share":0.0416,"seconds":64},{"topic":"UN reform","share":0.0411,"seconds":64},{"topic":"AI transformation","share":0.0408,"seconds":63},{"topic":"North Macedonia sovereignty","share":0.0408,"seconds":63},{"topic":"UN multilateralism","share":0.0407,"seconds":63},{"topic":"North Macedonia peacekeeping","share":0.0407,"seconds":63},{"topic":"Disinformation","share":0.0403,"seconds":63},{"topic":"International system trust","share":0.0398,"seconds":62},{"topic":"UN rules","share":0.0397,"seconds":62},{"topic":"UN alliances","share":0.0396,"seconds":62},{"topic":"North Macedonia youth","share":0.0393,"seconds":61},{"topic":"International rules","share":0.0391,"seconds":61}],"timeline":[[7,75,"North Macedonia education"],[76,140,"AI transformation"],[141,202,"North Macedonia education"],[203,266,"North Macedonia peacekeeping"],[268,334,"Small states"],[335,405,"North Macedonia foreign policy"],[406,468,"UN alliances"],[469,532,"UN multilateralism"],[533,595,"International system trust"],[596,678,"North Macedonia EU accession"],[679,742,"Institutional trust"],[743,804,"EU integration"],[805,867,"Disinformation"],[868,929,"Institutional trust"],[930,990,"International rules"],[991,1056,"International order"],[1057,1143,"EU integration"],[1147,1217,"AI infrastructure"],[1218,1284,"Migration policy"],[1286,1349,"UN reform"],[1350,1414,"North Macedonia sovereignty"],[1414,1476,"UN rules"],[1477,1538,"North Macedonia youth"],[1539,1587,"Small states"]],"stances":{"North Macedonia education":"Hristijan Mickoski states that a child starting school this autumn will become an adult in 2040 and notes the uncertainty of their future world.","AI transformation":"Hristijan Mickoski states that artificial intelligence will transform professions, industries, and decision-making processes.","North Macedonia peacekeeping":"Hristijan Mickoski states that North Macedonia chose peace and stability during the Yugoslav wars, leading to the UN establishing its first preventive peacekeeping mission on its territory.","Small states":"Hristijan Mickoski argues that small countries cannot afford geopolitical mistakes or indifference to international rules due to their lack of strategic flexibility compared to great powers.","North Macedonia foreign policy":"Hristijan Mickoski states that North Macedonia's geopolitical orientation is unified around being a NATO ally, having the United States as a strategic partner, and seeking full EU membership.","UN alliances":"Hristijan Mickoski argues that clear alliances and international institutions like the UN are essential for global cooperation without permanent divisions.","UN multilateralism":"Hristijan Mickoski argues that the United Nations should be strengthened and defended despite its imperfections, as it is essential for preventing a more dangerous world.","International system trust":"Hristijan Mickoski argues that trust in the international system is being jeopardized because rules are not applied equally and power often takes precedence over principle.","North Macedonia EU accession":"Hristijan Mickoski argues that North Macedonia has made excessive concessions for integration and asserts that trust must be reciprocal, with rules providing predictability for small states.","Institutional trust":"Hristijan Mickoski argues that institutions must demonstrate enduring value and commitments to earn citizen trust, and that rules should not change based on shifting power balances.","EU integration":"Hristijan Mickoski argues that the credibility of European and Euroatlantic integration is undermined when international rules are applied inconsistently and power overrides principle.","Disinformation":"Hristijan Mickoski states that politics is entering a more complex era due to widespread manipulation and disinformation, requiring leaders to earn public trust rather than just inform citizens.","International rules":"Hristijan Mickoski argues that abandoning established international principles during periods of rapid change is dangerous, particularly for small states.","International order":"Hristijan Mickoski argues that leaders must uphold rules and institutions despite their imperfections rather than abandoning the international order.","AI infrastructure":"Hristijan Mickoski states that artificial intelligence is no longer a future subject but current infrastructure and that the international order is shaped by technological capabilities.","Migration policy":"Hristijan Mickoski argues that migration is driven by a lack of security, employment, and education, and that policies must balance security with human dignity and labor market needs.","UN reform":"Hristijan Mickoski argues that the United Nations requires reform to effectively deliver results and build trust, while emphasizing that multilateralism extends beyond New York.","North Macedonia sovereignty":"Hristijan Mickoski defines modern sovereignty as a state that is trusted by allies, respects diversity, defends its identity without denying others, and does not rely on external forces to build it.","UN rules":"Hristijan Mickoski argues that small nations must support the UN to prevent a world where only the strongest are free and emphasizes the need for proactive rule-making regarding technology.","North Macedonia youth":"Hristijan Mickoski argues that societies must proactively build futures for young people and reform institutions before trust is lost, while advocating for a world based on dialogue rather than division."},"claims":[{"t":54,"quote":"a child who will sit at a school desk for the first time this autumn will in 2040 be a young person just entering adulthood.","topic":"North Macedonia education","kind":"fact"},{"t":82,"quote":"Artificial intelligence will transform professions, industries, and the ways in which decisions are made.","topic":"AI transformation","kind":"fact"},{"t":136,"quote":"More than 100 million people have been displaced by force.","topic":"AI transformation","kind":"number"},{"t":141,"quote":"More than 270 million children and young people are not in the school.","topic":"North Macedonia education","kind":"number"},{"t":194,"quote":"33 years ago, since we become a part of the United Nations, the world looked very different. The Cold War had ended.","topic":"North Macedonia education","kind":"fact"},{"t":215,"quote":"Yugoslavia was disintegrating in bloodshed. Wars were being fought just beyond our borders.","topic":"North Macedonia peacekeeping","kind":"fact"},{"t":234,"quote":"It was in those circumstances on our territory that the United Nations did something it had never done before. It established the first preventive peacekeeping mission in the history of the organization.","topic":"North Macedonia peacekeeping","kind":"fact"},{"t":282,"quote":"For a great power, a mistaken geopolitical calculation may mean a change of a strategy. For a small-sized country, the same mistake can mean a lost decade.","topic":"Small states","kind":"fact"},{"t":314,"quote":"Relations among the major power increasingly shaped trade. technology, energy, critical raw minerals, transport routes, and digital infrastructure.","topic":"Small states","kind":"fact"},{"t":382,"quote":"We are a NATO ally. The United States are our strategical partner. Full membership in the European Union is our strategic","topic":"North Macedonia foreign policy","kind":"fact"},{"t":406,"quote":"In a time of uncertaintity, our response is not strategic ambiguity. Our response is clarity.","topic":"UN alliances","kind":"fact"},{"t":510,"quote":"In 1954, Duck Hammershelt reminded us of a thought. The United Nations were not created to take us to heaven, but to save us from hell.","topic":"UN multilateralism","kind":"fact"},{"t":550,"quote":"Today, trust in the international system in being jeopardized precisely because too many people have a justified sense that the rules do not apply equally","topic":"International system trust","kind":"fact"},{"t":563,"quote":"that power sometimes take precedence over principle, that commitments are that agreements last only as long as interest remain unchanged","topic":"International system trust","kind":"fact"},{"t":614,"quote":"All they need is to look at the recent history of my A history marked by challenges, by security risks of regional proportions, by constant compromises and concessions made in the name of peace and cooperation and the higher goal of integration, often at the expense of most basic understanding of dignity and justice.","topic":"North Macedonia EU accession","kind":"fact"},{"t":639,"quote":"We have taken truly difficult decisions. We have continued forward even when processes lasted longer than one generation of citizens could reasonably have expected.","topic":"North Macedonia EU accession","kind":"self_credit"},{"t":679,"quote":"If candidates for membership in an organization are required to meet certain criteria, then meeting those criteria must progress.","topic":"Institutional trust","kind":"fact"},{"t":719,"quote":"We ask our citizens to believe in cooperation, in good neighborly relations, in compromises, and in mutual respect.","topic":"Institutional trust","kind":"fact"},{"t":760,"quote":"Principle sometimes gives way to power. that criteria can change while the process is already underway or that some are expected to demonstrate consistency that others do not always demand","topic":"EU integration","kind":"fact"},{"t":794,"quote":"citizens come to believe that their fate is created more often by the political weight of their state than by the strength of an agreed principle","topic":"EU integration","kind":"fact"},{"t":830,"quote":"We live in an age in which transformation travels around the world in a second. Never before has humanity had access to so much knowledge. But never before has it been exposed to so much manipulation, halftruths, fabricated images, propaganda and organized disinformation.","topic":"Disinformation","kind":"fact"},{"t":868,"quote":"We must build institutions they can trust when the truth is uncomfortable for everyone.","topic":"Institutional trust","kind":"fact"},{"t":875,"quote":"It is not enough to speak to them about values.","topic":"Institutional trust","kind":"fact"},{"t":930,"quote":"The world is changing at extraordinary speed. The centers of power are shifting. Technology is changing. Economic relations are changing. Security doctrines are changing. Alliances are changing.","topic":"International rules","kind":"fact"},{"t":1003,"quote":"Such a world does not exist.","topic":"International order","kind":"fact"},{"t":1067,"quote":"The European Union remains for us our natural political, economical and institutional home","topic":"EU integration","kind":"fact"},{"t":1106,"quote":"We are not asking for an easier path. We are asking for a path governed by rules.","topic":"EU integration","kind":"fact"},{"t":1166,"quote":"Artificial intelligence is not longer a subject of the future. It is infrastructure for today, for the present.","topic":"AI infrastructure","kind":"fact"},{"t":1174,"quote":"Today the world is once again recognizing the values of of reliable energy, of infrastructure, of diversified transport routes, of nearby and trusted supply chains.","topic":"AI infrastructure","kind":"fact"},{"t":1238,"quote":"Migration begins where there is no security, no employment, no education, no access to water, no prospects or no confidence that tomorrow will be better than today.","topic":"Migration policy","kind":"fact"},{"t":1267,"quote":"The green transition is essential.","topic":"Migration policy","kind":"fact"},{"t":1286,"quote":"If we expect poorer countries to move at the same pace without providing them with equal access to capital and technology, we will create injustice instead of a transition.","topic":"UN reform","kind":"fact"},{"t":1314,"quote":"Trust is not a sentiment that can be created by adopting a resolution. It is an outcome. It is built when an institution delivers on the purpose for which was established.","topic":"UN reform","kind":"fact"},{"t":1356,"quote":"Excellencies, we are a smalls size country, but we refuse to let the smallalness of our territory define the scale of our ambition.","topic":"North Macedonia sovereignty","kind":"fact"},{"t":1406,"quote":"This year, Secretary General Antonio Gutes reminded us on the charter begins with the worlds.","topic":"North Macedonia sovereignty","kind":"fact"},{"t":1417,"quote":"Not we powerful, not we the victors.","topic":"UN rules","kind":"fact"},{"t":1453,"quote":"Some decades ago, the United Nations came to our country with a new idea that the international community does not have to wait for a violence to begin before it acts.","topic":"UN rules","kind":"fact"},{"t":1503,"quote":"That child with whom I began will be 14 years old when the world enters in 2014.","topic":"North Macedonia youth","kind":"fact"},{"t":1539,"quote":"A world in which technology serves humanity. A world in which a small state has the right to the same dignity to the same rules at the same voice as a great powers.","topic":"Small states","kind":"fact"}],"promises":[{"t":1062,"quote":"We will not abandon the European idea because the European path has been difficult.","topic":"EU integration","kind":"promise"},{"t":1076,"quote":"We must strengthen the rule of law, build more effective institutions, build a more competitive economy and strengthen our citizens confidence in their own state.","topic":"EU integration","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":7,"topic":"North Macedonia education","text":"The assembly will hear an address by His Excellency Christian Mskosski, President of the Government of the Republic of North Macedonia. I request protocol to escort his excellency and invite him to address the Mr. President, Mr. Secretary General, excellencies, ladies and gentlemen, a child who will sit at a school desk for the first time this autumn will in 2040 be a young person just entering adulthood. We do not know exactly what the world in which that young person will live will look like."},{"t":76,"topic":"AI transformation","text":"But we already know that it will be a different from our own. Artificial intelligence will transform professions, industries, and the ways in which decisions are made. Energy will be governed by a new configuration and a new logic of operation. Climate change will affect economies, agriculture, cities, and the movement of people. Demographic change will reshape labor markets and social protection systems. Security will no longer depend on armies and borders, but also on power grids, data centers, cables, satellites, algorithms, and trust in the information we receive every day. And yet today, as we prepare for the future, millions of people are living through war or under the threat of war. More than 100 million people have been displaced by force."},{"t":141,"topic":"North Macedonia education","text":"More than 270 million children and young people are not in the school. This is the paradox of our time. Humanity has never possessed such immense scientific and technological capabilities. And yet it has never been more evident that technological capability does not automatically produce political wisdom. That is why the real question before this assembly is not simply how we will manage the crisis of 2026. The real question is this. What kind of international order will leave to the generations that is entering school For a smallsized country like mine, this is not an academic question. It is a question of survival. 33 years ago, since we become a part of the United Nations, the world looked very different. The Cold War had ended."},{"t":203,"topic":"North Macedonia peacekeeping","text":"There was hope that a new era was beginning, an era in which cooperation would gradually replace confrontation. Our region, however, was living through a very different reality. Yugoslavia was disintegrating in bloodshed. Wars were being fought just beyond our borders. The fear that the violence might spread was real. And yet my country choose peace. It choose stability. It was in those circumstances on our territory that the United Nations did something it had never done before. It established the first preventive peacekeeping mission in the history of the organization. That experience left a profound lesson in our national memory. A lesson to which I will return towards the end of my speech. Peace does not begin when war ends. Peace begins when politics is wise enough to prevent war from beginning."},{"t":268,"topic":"Small states","text":"Perhaps that is why small countries sometimes see international politics differently. Great powers have room for strategic shifts that small-sized states simply do not have. For a great power, a mistaken geopolitical calculation may mean a change of a strategy. For a small-sized country, the same mistake can mean a lost decade. That is why we cannot afford to be indifferent to the rules. Nor can we afford to believe that the rules will defend themselves. The world taking shape before us is a world of sharper competition. Power is being redistributed. Relations among the major power increasingly shaped trade. technology, energy, critical raw minerals, transport routes, and digital infrastructure. What we called economic interdependence yesterday, we increasingly see today as a matter of national security."},{"t":335,"topic":"North Macedonia foreign policy","text":"Globalization is not disappearing, it is being reshaped. Supply chain are changing. Production is once again becoming a geopolitical States are asking not only where something can be produced most cheaply, but who can be trusted. Not only where energy comes from, but whether it will be available when crisis strikes. Not only who develops the next generation of technology, but who will set the rules under which it will operate. alliances to are changing under the pressure of this same world. Macedonian citizens know where they belong. We are a NATO ally. The United States are our strategical partner. Full membership in the European Union is our strategic These are not three separate policies. They are one geopolitical orientation, an orientation grounded in democracy, collective security, the rule of law, and an open economy."},{"t":406,"topic":"UN alliances","text":"In a time of uncertaintity, our response is not strategic ambiguity. Our response is clarity. But clarity in our alliances does not mean turning away from the world. Quite the opposite. It is a precisely state that is confident in its democratic and strategic choices that can engage and cooperate with greater confidence with countries that have different histories, different interests and different political perspectives. The world does not need yet another division into permanent camps. It needs competition with limits and rules that all must respect. Alliances that take responsibility and international institutions that remain a space for a dialogue precisely when dialogue is most difficult. That is why the United Nations matters. Not because they can resolve every conflict."},{"t":469,"topic":"UN multilateralism","text":"Clearly they cannot. Not because every resolution is given effect. Clearly, that is not always the case. And that should not discourage us. It should strengthen our determination to protect this United Nations and the rules upon which they are founded and to stand for multilateralism grounded in values, mutual respect, and rules. Because a world without a place where all states, regardless of their size, can sit under the same roof and invoke the same principles, would be even more dangerous than the world we see today. In 1954, Duck Hammershelt reminded us of a thought. The United Nations were not created to take us to heaven, but to save us from hell. Seven decades later, it is worth understanding the essence of that statement. We should not demand perfection from United Nations."},{"t":533,"topic":"International system trust","text":"We should demand relevance, the capacity to prevent and to mediate, the capacity to protect human dignity, and ultimately the capacity to uphold principles even when applying them is politically Today, trust in the international system in being jeopardized precisely because too many people have a justified sense that the rules do not apply equally, that power sometimes take precedence over principle, that commitments are that agreements last only as long as interest remain unchanged. For small-siz states, this is an especially dangerous world. Our own history has taught us that international compromises are very difficult and that peace, stability, and integration require political courage and hard sacrifices."},{"t":596,"topic":"North Macedonia EU accession","text":"And without wishing to sound if anyone wants to see an example of a country that has repeatedly given up something that naturally belongs to it as a fundamental right, something that many take for granted. All they need is to look at the recent history of my A history marked by challenges, by security risks of regional proportions, by constant compromises and concessions made in the name of peace and cooperation and the higher goal of integration, often at the expense of most basic understanding of dignity and justice. We have taken truly difficult decisions. We have continued forward even when processes lasted longer than one generation of citizens could reasonably have expected. But precisely for that reason with the benefit of distance from those decisions and with a clear awareness of reality I can responsibly say today that trust cannot be a one-way obligation If small-siz states are expected to comply with the rules, then the rules must also provide them with predictability."},{"t":679,"topic":"Institutional trust","text":"If candidates for membership in an organization are required to meet certain criteria, then meeting those criteria must progress. If we ask citizen to trust institutions then institutions must demonstrate that their worth has value and that their commitments endure. The rule that applies today cannot be different tomorrow simply because the balance of powers has changed and a commitment undertaken cannot be a temporary political convenience. It must be a foundation on which people can plan their future. We ask our citizens to believe in cooperation, in good neighborly relations, in compromises, and in mutual respect. We tell them that lasting peace is worth more than a short-term political victory. That respecting agreements is a sign of strength and wisdom and that it is the right thing to do, not a sign of weakness."},{"t":743,"topic":"EU integration","text":"The European and Euroatlantic integration means accepting rules that apply equally to all. But that argument becomes much harder to sustain when citizens see that in international relations. Principle sometimes gives way to power. that criteria can change while the process is already underway or that some are expected to demonstrate consistency that others do not always demand of We cannot tell people trust the rules when they can see that the rules do not apply equally. We cannot convince them that compromise is a virtue if every compromise produces a new demand. And we cannot expect trust in international institutions. If citizens come to believe that their fate is created more often by the political weight of their state than by the strength of an agreed principle."},{"t":805,"topic":"Disinformation","text":"This is a question of because our our authority as elected leaders does not derive from the office itself. It deres from the people who elect us, who hold us to account and who every day compare what we tell them with what they see. And today they see more than ever before. We live in an age in which transformation travels around the world in a second. Never before has humanity had access to so much knowledge. But never before has it been exposed to so much manipulation, halftruths, fabricated images, propaganda and organized disinformation. That is precisely why politics is entering a new more difficult and more complex era. Our task is not longer simply to inform our citizens. We must earn their trust. It is not enough to tell them what is true."},{"t":868,"topic":"Institutional trust","text":"We must build institutions they can trust when the truth is uncomfortable for everyone. It is not enough to speak to them about values. We must show that those values have meaning and carry cost even when defending them requires patience, political capital or choosing the more difficult path. We are called upon to convince our societies that cooperation is better than isolation. That rule of law is better than unilateral behavior, that compromise is better than conflict, and that institutions are better than rule of sheer force. But for the conviction to carry weight, we ourselves must be consistent. Values are not sustained by speeches. They are sustained when they are upheld precisely at the moment when it is easiest to abandon them and many may be greatest challenges of our time."},{"t":930,"topic":"International rules","text":"The world is changing at extraordinary speed. The centers of power are shifting. Technology is changing. Economic relations are changing. Security doctrines are changing. Alliances are changing. Histories accelerating once again. In such a periods, there is always a temptation to declare that old principles are no longer practical, that the law must adapt to power, that values are a luxury that can wait until the crisis has But that is precisely when we need them most. Because if in times of change we abandon the rules that protected us in times of stability, we will not gain greater freedom, we will inherit a world in which every subsequent decision depends on who has more power at that particular moment. And such a world is especially dangerous for small size states."},{"t":991,"topic":"International order","text":"That is why our duty as leaders is not to promise our people a world without injustice, without disappointment and without conflict interests. Such a world does not exist. Our duty is far more demanding. To preserve fate in the rules even when it is a clear that the rules are being broken. To defend cooperation even when confrontation appears more popular. To sustain trust in institutions. No by asking people to look less closely and ask fewer questions but by making institutions more worthy of their trust. and not to allow disappointment with the imperfections of the international order to lead us towards something far worse. A world in which there is no order at all. That in my view is one of the greatest political and moral responsibilities of our generation."},{"t":1057,"topic":"EU integration","text":"It applies to the international system and it applies to Europe. We will not abandon the European idea because the European path has been difficult. The European Union remains for us our natural political, economical and institutional home and we have to work to do at home. We must strengthen the rule of law, build more effective institutions, build a more competitive economy and strengthen our citizens confidence in their own state. That is our responsibility and we will not shift it to Brussels. At the same time, we expect European integration to remain a merit-based process based on measurable criteria, not a process in which bilateral issues can continually move the goalposts. We are not asking for an easier path. We are asking for a path governed by rules. We are not asking for lower standards. We are asking for standards to remain standards. This is equally important for Europe's credibility at a time when its geopolitical weight will increasingly depend on its ability to translate its commitments into the tangible political outcome and on its resolve to uphold the values it exposes and to remain steadfast in advancing them despite the many challenges it face."},{"t":1147,"topic":"AI infrastructure","text":"the future international order will not be shaped only on battlefields or in diplomatic halls. It will be also shaped in laboratories, in schools, in factories, in energy grids, in data centers, and in the ability of societies to make sense of the changes that technology is bringing. Artificial intelligence is not longer a subject of the future. It is infrastructure for today, for the present. Today the world is once again recognizing the values of of reliable energy, of infrastructure, of diversified transport routes, of nearby and trusted supply chains. For us, the intensify development of corridor 8 and corridor 10 is a part of broader European vision to better connect the Adriatic, Yunian, the Black Sea, the Asian and Central Europe to provide goods, energy and people with more roots and greater connectivity and to ensure that the region becomes interconnected in the infrastructure rather than remaining on the political geopolitical periphery."},{"t":1218,"topic":"Migration policy","text":"Our geography does not have to be our destiny. It can be our advantage if we build the institutions and infrastructure that transform our geographical position into connectivity. At the same time, we must also approach migration definitely. Migration begins where there is no security, no employment, no education, no access to water, no prospects or no confidence that tomorrow will be better than today. It is not simply a matter of borders. Responsibly policy must bring together security, human dignity, development and the real needs of labor markets. Climate policy too will have to become more grounded in reality. The green transition is essential. But if we make it social unsustainable, we will lose the political support that is necessary to implement it. If we make it technologically dependent on handful of sources, we will create a new challenges while addressing old ones."},{"t":1286,"topic":"UN reform","text":"If we expect poorer countries to move at the same pace without providing them with equal access to capital and technology, we will create injustice instead of a transition. That is why future climate policy must at the same time be environmental policy, economic policy and social policy. Mr. President, all of these bring us back to the central theme of this session. Trust. Trust is not a sentiment that can be created by adopting a resolution. It is an outcome. It is built when an institution delivers on the purpose for which was established. That is why reform of United Nations is necessary so that the organization can become more so that it can deliver greater results and certainly not to replace the responsibility of national states but to act where collective action is needed. Multilateralism does not begin in New York."},{"t":1350,"topic":"North Macedonia sovereignty","text":"It begins when the quality of the states that came to New York. Excellencies, we are a smalls size country, but we refuse to let the smallalness of our territory define the scale of our ambition. Our ambition is to become a serious state. A state that its allies can trust. A state in which young people can plan their future. A state that respects the diversity and multicultural character of its society. A state confident enough to defend its own identity without denying the identity of the others. A state that knows its history but is not imprisoned by it. And a state that does not expect others to build it in its place. That to me is modern sovereignity, not isolation capability. This year, Secretary General Antonio Gutes reminded us on the charter begins with the worlds."},{"t":1414,"topic":"UN rules","text":"We the peoples and he added, \"Not we powerful, not we the victors.\" In those words lies the reason why smallsized European country continues to believe in this organization even when it is disappointed by it. Because the alternative to a world governed by rules is not a world in which everyone is free. It is a world in which the strongest are the freest and everyone else depends on their goodwill. Such a world may appear effective for a moment but it is never stable. Some decades ago, the United Nations came to our country with a new idea that the international community does not have to wait for a violence to begin before it acts. Today, we once again need to same political wisdom. We must not wait for a technology to create new inequalities before we establish rules."},{"t":1477,"topic":"North Macedonia youth","text":"We must not wait for young people to live before we build societies in which they see a future worth staying for. We must not wait for institutions to lose all public trust before we reform them. And we must not wait for the world to become fully divided into opposing blocks before we rediscover the values of a dialogue. That child with whom I began will be 14 years old when the world enters in 2014. None of us today can promise that child a peaceful world, nor a world without crisis, nor a world without competition. But we can leave that child something else. A world in which power is not the only argument. A world in which knowledge is not the privilege of you. A world in which alliances create security rather than new lines of fear."},{"t":1539,"topic":"Small states","text":"A world in which technology serves humanity. A world in which a small state has the right to the same dignity to the same rules at the same voice as a great powers. That is the promise worth renewing. Not because we are naive about the world as it is, but because we are realistic enough to understand what happens when the world is left to power alone. Macedonians and the Macedonian citizens will share their burden of responsibility. Thank you so much for your attention. On behalf of the assembly, I wish to thank the president of the government of the Republic of North Macedonia."}],"compare":[{"topic":"UN & its reform","share":0.2405,"mean":0.2046,"rank":73,"others":170},{"topic":"International Law & Order","share":0.1203,"mean":0.0601,"rank":38,"others":102},{"topic":"Europe","share":0.0945,"mean":0.0037,"rank":3,"others":8},{"topic":"Artificial Intelligence","share":0.0864,"mean":0.0503,"rank":44,"others":83},{"topic":"Small states","share":0.0734,"mean":0.0021,"rank":3,"others":6},{"topic":"Migration","share":0.0427,"mean":0.0047,"rank":12,"others":12},{"topic":"North Macedonia","share":0.0408,"mean":0.0,"rank":1,"others":0},{"topic":"Disinformation","share":0.0403,"mean":0.0009,"rank":3,"others":2}]};
